import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1788348328000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="the-tools-are-listed-but-every-call-fails" tabindex="-1">The tools are listed but every call fails <a class="header-anchor" href="#the-tools-are-listed-but-every-call-fails" aria-label="Permalink to “The tools are listed but every call fails”">​</a></h2><p>Expected when the configuration is incomplete: the server starts and handshakes without credentials on purpose, so registries and inspectors can enumerate its tools. The error text names the missing variables. Check your client is actually passing them — <code>claude mcp list</code>, or the <code>env</code> block in the config file.</p><p><code>get_server_status</code> is the cheapest real connectivity test.</p><h2 id="_401-or-403" tabindex="-1"><code>401</code> or <code>403</code> <a class="header-anchor" href="#_401-or-403" aria-label="Permalink to “401 or 403”">​</a></h2><ul><li><strong>401</strong> — the key is wrong, revoked, or not being passed.</li><li><strong>403</strong> — the key is valid but its user is not allowed. Remember the key acts as one Audiobookshelf user: a library that is not shared with that user returns 403, and deleting needs an account with delete permission. <code>get_me</code> shows you which user you are and what it may do.</li></ul><h2 id="_404-on-an-id-that-exists" tabindex="-1"><code>404</code> on an id that exists <a class="header-anchor" href="#_404-on-an-id-that-exists" aria-label="Permalink to “404 on an id that exists”">​</a></h2><p>Either it does not exist, or it belongs to a library the key&#39;s user cannot access — Audiobookshelf answers 404 in both cases, so the two are indistinguishable from here. Compare against <code>list_libraries</code> output for the same key.</p><p><code>get_media_progress</code> also returns 404 for an item that has simply never been started. That is not an error condition, just an absence.</p><h2 id="api-keys-do-not-exist-in-my-audiobookshelf" tabindex="-1">API keys do not exist in my Audiobookshelf <a class="header-anchor" href="#api-keys-do-not-exist-in-my-audiobookshelf" aria-label="Permalink to “API keys do not exist in my Audiobookshelf”">​</a></h2><p>They were added in <strong>2.26.0</strong>. Check with <code>curl -s https://abs.example.com/status</code>. Older servers only have the browser login flow (short-lived access token plus refresh rotation), which this server does not implement.</p><h2 id="a-filter-returns-my-whole-library" tabindex="-1">A filter returns my whole library <a class="header-anchor" href="#a-filter-returns-my-whole-library" aria-label="Permalink to “A filter returns my whole library”">​</a></h2><p>That used to be the trap this server exists to prevent. Audiobookshelf expects the <code>filter</code> parameter as <code>&lt;group&gt;.&lt;base64(value)&gt;</code> and treats an unknown group as a <em>valueless</em> filter — so a typo silently returns the unfiltered library instead of an error.</p><p><code>list_library_items</code> therefore validates: pass <code>filter_group</code> and <code>filter_value</code> separately, and a valued group without its value is rejected outright. Get the valid values from <code>get_library_filter_data</code>.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>filter_group=&quot;authors&quot;,  filter_value=&quot;&lt;author id&gt;&quot;</span></span>
<span class="line"><span>filter_group=&quot;progress&quot;, filter_value=&quot;finished&quot; | &quot;in-progress&quot; | &quot;not-started&quot; | &quot;not-finished&quot;</span></span>
<span class="line"><span>filter_group=&quot;issues&quot;    (standalone, takes no value)</span></span></code></pre></div><h2 id="a-response-was-still-too-big" tabindex="-1">A response was still too big <a class="header-anchor" href="#a-response-was-still-too-big" aria-label="Permalink to “A response was still too big”">​</a></h2><p>Ask for the compact form — that is the default, so check you are not passing <code>detail: &quot;full&quot;</code>. If a compact projection is genuinely too large for your case, that is worth an <a href="https://github.com/ni-c/audiobookshelf-mcp/issues" target="_blank" rel="noreferrer">issue</a>: the projections were tuned against a real library and can be tuned further.</p><p>For lists, lower <code>limit</code> (max 100) and page with <code>page</code>. List tools tell you the total and what to call next when more matches exist.</p><h2 id="chapters-are-missing-from-get-library-item" tabindex="-1">Chapters are missing from <code>get_library_item</code> <a class="header-anchor" href="#chapters-are-missing-from-get-library-item" aria-label="Permalink to “Chapters are missing from get_library_item”">​</a></h2><p>By design — a long audiobook can have hundreds. Use <code>get_item_chapters</code>, or <code>detail: &quot;full&quot;</code> for everything including audio files and tracks.</p><h2 id="get-item-chapters-says-my-item-is-a-podcast" tabindex="-1"><code>get_item_chapters</code> says my item is a podcast <a class="header-anchor" href="#get-item-chapters-says-my-item-is-a-podcast" aria-label="Permalink to “get_item_chapters says my item is a podcast”">​</a></h2><p>Podcast episodes do not have chapters in Audiobookshelf. Use <code>get_podcast_episode</code>.</p><h2 id="my-playlist-disappeared" tabindex="-1">My playlist disappeared <a class="header-anchor" href="#my-playlist-disappeared" aria-label="Permalink to “My playlist disappeared”">​</a></h2><p>Audiobookshelf deletes a playlist automatically when its last entry is removed. <code>remove_items_from_playlist</code> reports this in its result when it happens. It cannot be restored — recreate it with <code>create_playlist</code>.</p><h2 id="collections-vs-playlists" tabindex="-1">Collections vs. playlists <a class="header-anchor" href="#collections-vs-playlists" aria-label="Permalink to “Collections vs. playlists”">​</a></h2><ul><li><strong>Collections</strong> are shared server-wide, hold books only, and need at least one book (Audiobookshelf rejects an empty one).</li><li><strong>Playlists</strong> are private per user, may be empty, and can hold podcast episodes. A playlist is homogeneous: either every entry has an <code>episode_id</code> or none does.</li></ul><h2 id="self-signed-certificate" tabindex="-1">Self-signed certificate <a class="header-anchor" href="#self-signed-certificate" aria-label="Permalink to “Self-signed certificate”">​</a></h2><p>Add your CA to the system trust store if you can. Otherwise <code>AUDIOBOOKSHELF_INSECURE_TLS=true</code>, which scopes the relaxed validation to this connection only — see <a href="/guide/configuration">Configuration</a>.</p><h2 id="can-it-play-pause-or-seek" tabindex="-1">Can it play, pause or seek? <a class="header-anchor" href="#can-it-play-pause-or-seek" aria-label="Permalink to “Can it play, pause or seek?”">​</a></h2><p>No. Playback is a session state machine that belongs in a real client. <code>set_media_progress</code> moves your position, which covers &quot;mark this finished&quot; and &quot;jump me to chapter 12&quot;; your phone does the playing.</p><h2 id="can-it-add-podcasts-scan-the-library-or-edit-metadata" tabindex="-1">Can it add podcasts, scan the library or edit metadata? <a class="header-anchor" href="#can-it-add-podcasts-scan-the-library-or-edit-metadata" aria-label="Permalink to “Can it add podcasts, scan the library or edit metadata?”">​</a></h2><p>No, deliberately — see <a href="/guide/security">Security</a> for the full list of what is left out and why.</p><h2 id="which-tools-change-something" tabindex="-1">Which tools change something? <a class="header-anchor" href="#which-tools-change-something" aria-label="Permalink to “Which tools change something?”">​</a></h2><p>15 of the 44. Every tool declares all four MCP annotations — <code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code> — so a client that shows them can tell before it calls. The <a href="/reference/tools">tools reference</a> labels every one, and <code>AUDIOBOOKSHELF_READ_ONLY=true</code> removes all writes.</p><p>Annotations are advice a client may ignore; the eight marked 👤 also <strong>ask a person</strong>, which is enforced here and cannot be. See <a href="/guide/approval">Asking a person</a>.</p><p><code>update_collection</code> and <code>update_playlist</code> ask only for the half that replaces a curated order. <code>library_item_ids</code> / <code>items</code> reorders the entries that are already there — it adds nothing and removes nothing — but the order somebody arranged is gone afterwards, which is the same reason <code>remove_books_from_collection</code> asks. Renaming and re-describing stay free: those are recoverable by typing the old text back.</p><h2 id="a-tool-answered-with-a-confirm-token-instead-of-asking" tabindex="-1">A tool answered with a <code>confirm_token</code> instead of asking <a class="header-anchor" href="#a-tool-answered-with-a-confirm-token-instead-of-asking" aria-label="Permalink to “A tool answered with a confirm_token instead of asking”">​</a></h2><p>That is the fallback for a client that cannot show a dialog. Call the tool again with the same arguments plus the token; it is single-use and lasts five minutes. If your client <em>can</em> show dialogs, check whether <code>ELICITATION</code> is set to <code>false</code> somewhere in the environment — it carries no prefix, so it may have been meant for a different server.</p><h2 id="where-do-i-report-a-problem" tabindex="-1">Where do I report a problem? <a class="header-anchor" href="#where-do-i-report-a-problem" aria-label="Permalink to “Where do I report a problem?”">​</a></h2><ul><li>Questions and ideas → <a href="https://github.com/ni-c/audiobookshelf-mcp/discussions" target="_blank" rel="noreferrer">Discussions</a></li><li>Reproducible problems → <a href="https://github.com/ni-c/audiobookshelf-mcp/issues" target="_blank" rel="noreferrer">Issues</a></li><li>Vulnerabilities → <a href="https://github.com/ni-c/audiobookshelf-mcp/security/advisories/new" target="_blank" rel="noreferrer">private reporting</a></li></ul><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Something narrowed the list. In order of likelihood:</p><ul><li><code>AUDIOBOOKSHELF_READ_ONLY</code> is set, and it is a write tool.</li><li><code>AUDIOBOOKSHELF_ALLOW_TOOLS</code> is set and does not name it — it is an allow list, so anything not named is out.</li><li><code>AUDIOBOOKSHELF_DENY_TOOLS</code> names it, possibly through a prefix such as <code>list_*</code>.</li></ul><p>A filtered tool is not registered at all, so it is missing from <code>tools/list</code> and answers <code>tools/call</code> with &quot;tool not found&quot;. There is no state where it is hidden but still callable.</p><p>What it is <em>not</em> is a typo in one of those variables: an entry that matches no tool stops the server at startup and says which entry it was. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p>`,45)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};